use rayon::prelude::*;
use std::{
    cmp::Ordering,
    fs::File,
    io::{BufReader, Read},
    path::Path,
};

#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Neighbor {
    pub id: usize,
    pub squared_distance: f32,
}

#[derive(Debug)]
struct InvertedList {
    codes: Vec<f32>,
    ids: Vec<usize>,
}

/// A native, in-memory reader and L2 search implementation for FAISS `IndexIVFFlat`.
/// Supports the `IwFl` / `IxF2` / `ilar` format generated by the RVC training pipeline.
/// Embedding data remains in this owner; lookups do not depend on Python or FAISS shared libraries.
pub struct IvfFlatIndex {
    dimension: usize,
    total: usize,
    nprobe: usize,
    centroids: Vec<f32>,
    lists: Vec<InvertedList>,
    id_locations: Vec<(usize, usize)>,
}

impl IvfFlatIndex {
    pub fn open(path: impl AsRef<Path>) -> Result<Self, String> {
        let file = File::open(path.as_ref()).map_err(|e| format!("open FAISS index: {e}"))?;
        Self::read(BufReader::new(file))
    }

    pub fn read(mut input: impl Read) -> Result<Self, String> {
        read_tag(&mut input, b"IwFl")?;
        let (dimension, total) = read_index_header(&mut input)?;
        let nlist = read_size(&mut input)?;
        let nprobe = read_size(&mut input)?;
        if nlist == 0 || nlist > 1_000_000 || nprobe == 0 || nprobe > nlist {
            return Err("invalid IVF nlist or nprobe".into());
        }
        read_tag(&mut input, b"IxF2")?;
        let (coarse_dimension, coarse_total) = read_index_header(&mut input)?;
        if coarse_dimension != dimension || coarse_total != nlist {
            return Err("IVF coarse quantizer dimensions/count mismatch".into());
        }
        let centroid_elements = checked_mul(nlist, dimension)?;
        if read_size(&mut input)? != centroid_elements {
            return Err("unexpected IVF centroid vector length".into());
        }
        let centroids = read_f32_vector(&mut input, centroid_elements)?;
        if centroids.iter().any(|value| !value.is_finite()) {
            return Err("non-finite IVF centroid".into());
        }

        let direct_map_type = read_u8(&mut input)?;
        let direct_map_entries = read_size(&mut input)?;
        if direct_map_type != 0 || direct_map_entries != 0 {
            return Err("FAISS direct map other than NoMap is not supported".into());
        }
        read_tag(&mut input, b"ilar")?;
        if read_size(&mut input)? != nlist || read_size(&mut input)? != checked_mul(dimension, 4)? {
            return Err("IVF inverted list metadata is incompatible with flat FP32 vectors".into());
        }
        read_tag(&mut input, b"full")?;
        if read_size(&mut input)? != nlist {
            return Err("IVF inverted list sizes count mismatch".into());
        }
        let mut sizes = Vec::with_capacity(nlist);
        for _ in 0..nlist {
            sizes.push(read_size(&mut input)?);
        }
        let vector_total = sizes
            .iter()
            .try_fold(0_usize, |a, b| a.checked_add(*b))
            .ok_or("IVF list sizes overflow")?;
        if vector_total != total {
            return Err(format!(
                "IVF list sizes add up to {vector_total}, expected {total}"
            ));
        }
        if total > 10_000_000 || checked_mul(total, dimension)? > 100_000_000 {
            return Err("IVF index exceeds native loader safety limits".into());
        }
        let mut lists = Vec::with_capacity(nlist);
        let mut id_locations = vec![(usize::MAX, usize::MAX); total];
        for (list_index, size) in sizes.into_iter().enumerate() {
            let codes = read_f32_vector(&mut input, checked_mul(size, dimension)?)?;
            if codes.iter().any(|value| !value.is_finite()) {
                return Err("non-finite IVF stored vector".into());
            }
            let mut ids = Vec::with_capacity(size);
            for slot in 0..size {
                let id = read_size(&mut input)?;
                if id >= total || id_locations[id].0 != usize::MAX {
                    return Err(format!("invalid or duplicate IVF vector ID {id}"));
                }
                id_locations[id] = (list_index, slot);
                ids.push(id);
            }
            lists.push(InvertedList { codes, ids });
        }
        if id_locations.iter().any(|(i, _)| *i == usize::MAX) {
            return Err("IVF ID table is not dense".into());
        }
        let mut trailing = [0_u8];
        if input.read(&mut trailing).map_err(|e| e.to_string())? != 0 {
            return Err("unexpected trailing data after IVF lists".into());
        }
        Ok(Self {
            dimension,
            total,
            nprobe,
            centroids,
            lists,
            id_locations,
        })
    }

    pub fn dimension(&self) -> usize {
        self.dimension
    }
    pub fn len(&self) -> usize {
        self.total
    }
    pub fn is_empty(&self) -> bool {
        self.total == 0
    }
    pub fn nlist(&self) -> usize {
        self.lists.len()
    }
    pub fn nprobe(&self) -> usize {
        self.nprobe
    }

    pub fn reconstruct(&self, id: usize) -> Option<&[f32]> {
        let &(list, slot) = self.id_locations.get(id)?;
        let start = slot * self.dimension;
        Some(&self.lists[list].codes[start..start + self.dimension])
    }

    pub fn search(&self, query: &[f32], k: usize) -> Result<Vec<Neighbor>, String> {
        self.search_with_nprobe(query, k, self.nprobe)
    }

    pub fn search_with_nprobe(
        &self,
        query: &[f32],
        k: usize,
        nprobe: usize,
    ) -> Result<Vec<Neighbor>, String> {
        if query.len() != self.dimension || query.iter().any(|x| !x.is_finite()) {
            return Err("FAISS query dimension mismatch or non-finite element".into());
        }
        if nprobe == 0 || nprobe > self.nlist() || k == 0 {
            return Err("FAISS search requires positive k and nprobe <= nlist".into());
        }
        let selected: Vec<usize> = if nprobe == 1 {
            vec![self.nearest_centroid_exact(query)]
        } else {
            let mut centroids: Vec<(usize, f32)> = self
                .centroids
                .chunks_exact(self.dimension)
                .enumerate()
                .map(|(i, centroid)| (i, squared_l2(query, centroid)))
                .collect();
            centroids.select_nth_unstable_by(nprobe - 1, |a, b| order_by_distance(a.1, a.0, b.1, b.0));
            centroids[..nprobe].iter().map(|(i, _)| *i).collect()
        };
        let mut neighbors = Vec::new();
        for index in selected {
            let list = &self.lists[index];
            for (slot, stored) in list.codes.chunks_exact(self.dimension).enumerate() {
                neighbors.push(Neighbor {
                    id: list.ids[slot],
                    squared_distance: squared_l2(query, stored),
                });
            }
        }
        neighbors.sort_unstable_by(|a, b| {
            order_by_distance(a.squared_distance, a.id, b.squared_distance, b.id)
        });
        neighbors.truncate(k);
        Ok(neighbors)
    }

    fn nearest_centroid_exact(&self, query: &[f32]) -> usize {
        let mut centroids = self.centroids.chunks_exact(self.dimension).enumerate();
        let (_, first) = centroids.next().expect("nonempty IVF centroids");
        let mut best = (0usize, squared_l2(query, first));
        for (id, centroid) in centroids {
            if let Some(distance) = squared_l2_bounded(query, centroid, best.1) {
                if order_by_distance(distance, id, best.1, best.0).is_lt() {
                    best = (id, distance);
                }
            }
        }
        best.0
    }

    /// Apply the original RVC inverse-square-distance 8-NN retrieval blend in the
    /// source HuBERT feature space, before frame upsampling and TextEncoder.
    pub fn blend_features(&self, features: &mut [f32], index_rate: f32) -> Result<(), String> {
        if features.len() % self.dimension != 0
            || !index_rate.is_finite()
            || !(0.0..=1.0).contains(&index_rate)
        {
            return Err("invalid RVC feature matrix or index_rate".into());
        }
        if index_rate == 0.0 {
            return Ok(());
        }
        let rows = features.len() / self.dimension;
        if rows >= 32 {
            features.par_chunks_exact_mut(self.dimension)
                .try_for_each(|query| self.blend_row(query, index_rate))
        } else {
            features.chunks_exact_mut(self.dimension)
                .try_for_each(|query| self.blend_row(query, index_rate))
        }
    }

    fn blend_row(&self, query: &mut [f32], index_rate: f32) -> Result<(), String> {
        let mut average = vec![0.0f32; self.dimension];
            let neighbors = self.search(query, 8)?;
            if neighbors.len() != 8 {
                return Ok(());
            }
            let zeros: Vec<_> = neighbors
                .iter()
                .filter(|n| n.squared_distance == 0.0)
                .collect();
            let weights: Vec<f32> = if zeros.is_empty() {
                let raw: Vec<f32> = neighbors
                    .iter()
                    .map(|n| 1.0 / n.squared_distance.max(f32::MIN_POSITIVE).powi(2))
                    .collect();
                let sum: f32 = raw.iter().sum();
                if !sum.is_finite() || sum == 0.0 {
                    return Err("invalid FAISS retrieval distance weights".into());
                }
                raw.into_iter().map(|w| w / sum).collect()
            } else {
                neighbors
                    .iter()
                    .map(|n| {
                        if n.squared_distance == 0.0 {
                            1.0 / zeros.len() as f32
                        } else {
                            0.0
                        }
                    })
                    .collect()
            };
            average.fill(0.0);
            for (neighbor, weight) in neighbors.iter().zip(weights) {
                let vector = self
                    .reconstruct(neighbor.id)
                    .ok_or("FAISS reconstructed ID missing")?;
                for (x, element) in average.iter_mut().zip(vector) {
                    *x += weight * element;
                }
            }
            for (x, retrieved) in query.iter_mut().zip(average.iter()) {
                *x = *x * (1.0 - index_rate) + retrieved * index_rate;
            }
        Ok(())
    }
}

fn squared_l2(a: &[f32], b: &[f32]) -> f32 {
    a.iter().zip(b).map(|(x, y)| (x - y) * (x - y)).sum()
}

fn squared_l2_bounded(a: &[f32], b: &[f32], bound: f32) -> Option<f32> {
    let mut total = 0.0f32;
    for (left, right) in a.chunks(32).zip(b.chunks(32)) {
        for (&x, &y) in left.iter().zip(right) {
            total += (x - y) * (x - y);
        }
        if total > bound {
            return None;
        }
    }
    Some(total)
}

fn order_by_distance(a: f32, a_id: usize, b: f32, b_id: usize) -> Ordering {
    a.total_cmp(&b).then_with(|| a_id.cmp(&b_id))
}

fn checked_mul(a: usize, b: usize) -> Result<usize, String> {
    a.checked_mul(b)
        .ok_or_else(|| "FAISS index dimension multiplication overflow".into())
}

fn read_exact<const N: usize>(reader: &mut impl Read) -> Result<[u8; N], String> {
    let mut bytes = [0; N];
    reader
        .read_exact(&mut bytes)
        .map_err(|e| format!("truncated/corrupt FAISS index: {e}"))?;
    Ok(bytes)
}

fn read_tag(reader: &mut impl Read, expected: &[u8; 4]) -> Result<(), String> {
    let tag = read_exact::<4>(reader)?;
    if tag != *expected {
        return Err(format!(
            "unsupported FAISS tag {:?}, expected {:?}",
            tag, expected
        ));
    }
    Ok(())
}

fn read_u8(reader: &mut impl Read) -> Result<u8, String> {
    Ok(read_exact::<1>(reader)?[0])
}
fn read_i32(reader: &mut impl Read) -> Result<i32, String> {
    Ok(i32::from_le_bytes(read_exact(reader)?))
}
fn read_i64(reader: &mut impl Read) -> Result<i64, String> {
    Ok(i64::from_le_bytes(read_exact(reader)?))
}
fn read_size(reader: &mut impl Read) -> Result<usize, String> {
    usize::try_from(u64::from_le_bytes(read_exact(reader)?)).map_err(|e| e.to_string())
}

fn read_index_header(reader: &mut impl Read) -> Result<(usize, usize), String> {
    let d = read_i32(reader)?;
    let total = read_i64(reader)?;
    let _legacy_dummy_a = read_i64(reader)?;
    let _legacy_dummy_b = read_i64(reader)?;
    let trained = read_u8(reader)?;
    let metric = read_i32(reader)?;
    if d <= 0 || d > 65_536 || total < 0 || trained != 1 || metric != 1 {
        return Err("only trained L2 FAISS IndexIVFFlat indexes are supported".into());
    }
    Ok((d as usize, total as usize))
}

fn read_f32_vector(reader: &mut impl Read, elements: usize) -> Result<Vec<f32>, String> {
    let mut bytes = vec![0; checked_mul(elements, 4)?];
    reader
        .read_exact(&mut bytes)
        .map_err(|e| format!("truncated FAISS vector data: {e}"))?;
    Ok(bytes
        .chunks_exact(4)
        .map(|chunk| f32::from_le_bytes(chunk.try_into().unwrap()))
        .collect())
}

#[cfg(test)]
mod tests {
    use super::*;

    fn build_fixture() -> Vec<u8> {
        let mut output = Vec::new();
        let tag = |out: &mut Vec<u8>, s: &[u8]| out.extend_from_slice(s);
        let u64_ = |out: &mut Vec<u8>, n: u64| out.extend(n.to_le_bytes());
        let header = |out: &mut Vec<u8>, ntotal: u64| {
            out.extend(2_i32.to_le_bytes());
            u64_(out, ntotal);
            u64_(out, 1 << 20);
            u64_(out, 1 << 20);
            out.push(1);
            out.extend(1_i32.to_le_bytes());
        };
        tag(&mut output, b"IwFl");
        header(&mut output, 9);
        u64_(&mut output, 2);
        u64_(&mut output, 1);
        tag(&mut output, b"IxF2");
        header(&mut output, 2);
        u64_(&mut output, 4);
        for x in [0.0_f32, 0.0, 100.0, 100.0] {
            output.extend(x.to_le_bytes());
        }
        output.push(0);
        u64_(&mut output, 0);
        tag(&mut output, b"ilar");
        u64_(&mut output, 2);
        u64_(&mut output, 8);
        tag(&mut output, b"full");
        u64_(&mut output, 2);
        u64_(&mut output, 8);
        u64_(&mut output, 1);
        for id in 0..8_u64 {
            output.extend((id as f32).to_le_bytes());
            output.extend(0_f32.to_le_bytes());
        }
        for id in 0..8_u64 {
            u64_(&mut output, id);
        }
        for x in [100_f32, 100_f32] {
            output.extend(x.to_le_bytes());
        }
        u64_(&mut output, 8);
        output
    }

    #[test]
    fn loads_searches_and_reconstructs_faiss_ivf_flat() {
        let index = IvfFlatIndex::read(build_fixture().as_slice()).unwrap();
        assert_eq!(
            (
                index.dimension(),
                index.len(),
                index.nlist(),
                index.nprobe()
            ),
            (2, 9, 2, 1)
        );
        let found = index.search(&[1.0, 0.0], 3).unwrap();
        assert_eq!(
            found.iter().map(|item| item.id).collect::<Vec<_>>(),
            [1, 0, 2]
        );
        assert_eq!(index.reconstruct(8).unwrap(), &[100.0, 100.0]);
        assert_eq!(index.search(&[100.0, 100.0], 8).unwrap().len(), 1);
        assert!(index.search(&[1.0], 8).is_err());
    }

    #[test]
    fn uses_inverse_square_distance_and_respects_index_rate() {
        let index = IvfFlatIndex::read(build_fixture().as_slice()).unwrap();
        let mut query = [3.0, 0.0];
        index.blend_features(&mut query, 1.0).unwrap();
        assert!((query[0] - 3.0).abs() < 1e-5);
        let mut query = [3.4, 0.0];
        index.blend_features(&mut query, 0.0).unwrap();
        assert_eq!(query, [3.4, 0.0]);
        index.blend_features(&mut query, 0.5).unwrap();
        assert!(query[0] > 3.0 && query[0] < 3.5);
    }

    #[test]
    fn parallel_blend_matches_sequential_for_many_frames() {
        let index = IvfFlatIndex::read(build_fixture().as_slice()).unwrap();
        let mut serial = (0..64).flat_map(|i| [i as f32 / 20.0, 0.0]).collect::<Vec<_>>();
        let mut parallel = serial.clone();
        for row in serial.chunks_exact_mut(index.dimension()) {
            index.blend_row(row, 0.75).unwrap();
        }
        index.blend_features(&mut parallel, 0.75).unwrap();
        assert_eq!(serial, parallel);
    }

    #[test]
    fn bounded_l2_preserves_exact_fp32_distances_when_not_pruned() {
        for dimension in [1, 7, 31, 32, 33, 65, 768] {
            for offset in [0, 1, 13, 41] {
                let left: Vec<f32> = (0..dimension)
                    .map(|i| ((i * 17 + offset * 7) % 89) as f32 / 91.0)
                    .collect();
                let right: Vec<f32> = (0..dimension)
                    .map(|i| ((i * 29 + offset * 11) % 101) as f32 / 103.0)
                    .collect();
                let exact = squared_l2(&left, &right);
                for bound in [0.0, exact / 2.0, exact, exact + 1.0, f32::INFINITY] {
                    match squared_l2_bounded(&left, &right, bound) {
                        Some(actual) => assert_eq!(actual.to_bits(), exact.to_bits()),
                        None => assert!(exact > bound),
                    }
                }
            }
        }
    }

    #[test]
    fn bounded_centroid_selection_preserves_ties_and_full_scan() {
        let index = IvfFlatIndex::read(build_fixture().as_slice()).unwrap();
        for value in 0..1024 {
            let query = [value as f32 / 10.0 - 10.0, (value % 13) as f32 / 10.0];
            let exhaustive = index.centroids.chunks_exact(index.dimension).enumerate()
                .map(|(id, centroid)| (id, squared_l2(&query, centroid)))
                .min_by(|a, b| order_by_distance(a.1, a.0, b.1, b.0)).unwrap().0;
            assert_eq!(index.nearest_centroid_exact(&query), exhaustive);
        }
        let identical_centroids = [0.0f32, 0.0, 0.0, 0.0];
        let index = IvfFlatIndex { centroids: identical_centroids.to_vec(), ..index };
        assert_eq!(index.nearest_centroid_exact(&[0.0, 0.0]), 0);
    }

    #[test]
    fn real_index_centroids_match_full_scan_when_available() {
        let Ok(path) = std::env::var("RVC_REAL_FAISS_INDEX") else { return; };
        let index = IvfFlatIndex::open(path).unwrap();
        for row in 0..24 {
            let id = (row * 7_919 + 19) % index.len();
            let query: Vec<f32> = index.reconstruct(id).unwrap().iter().enumerate()
                .map(|(column, &value)| value + ((row * 17 + column * 13) % 11) as f32 * 0.0007)
                .collect();
            let expected = index.centroids.chunks_exact(index.dimension).enumerate()
                .map(|(i, centroid)| (i, squared_l2(&query, centroid)))
                .min_by(|a, b| order_by_distance(a.1, a.0, b.1, b.0)).unwrap().0;
            assert_eq!(index.nearest_centroid_exact(&query), expected, "row={row}");
        }
    }

    #[test]
    fn rejects_corruption() {
        let mut bytes = build_fixture();
        bytes[0] = b'X';
        assert!(IvfFlatIndex::read(bytes.as_slice()).is_err());
        let bytes = build_fixture();
        assert!(IvfFlatIndex::read(&bytes[..bytes.len() - 8]).is_err());
    }
}
